15: /// Normalize and validate a path. Rejects traversal and non-absolute paths.
16: ///
17: /// Accepts both Windows paths (`C:\a\b`, `\\server\share`) and rooted
18: /// POSIX-style paths (`/a/b`). The frontend's library paths are virtual
19: /// (`/folio-library/...`) and are mapped to a real directory before they reach
20: /// the guard, but the TS path tests also assert the POSIX form, so keep both
21: /// accepted here for parity.
22: pub fn normalize_absolute(input: &str) -> Result<PathBuf, GuardError> {
23:     if input.is_empty() {
24:         return Err(GuardError::NotAbsolute);
25:     }
26:     let p = Path::new(input);
27:     if !p.is_absolute() && !input.starts_with('/') {
28:         return Err(GuardError::NotAbsolute);
29:     }
30:     // Reject any parent components / traversal.
31:     for comp in p.components() {
32:         match comp {
33:             std::path::Component::ParentDir => return Err(GuardError::Traversal),
34:             std::path::Component::Normal(c) => {
35:                 let s = c.to_string_lossy();
36:                 if s.contains('\0') || s == ".." {
37:                     return Err(GuardError::Traversal);
38:                 }
39:             }
40:             _ => {}
41:         }
42:     }
43:     Ok(p.to_path_buf())
44: }
45: 
46: #[allow(dead_code)]
47: pub fn ensure_no_escape(root: Option<&Path>, target: &Path) -> Result<(), GuardError> {
48:     if let Some(r) = root {
49:         // Best-effort: target must start with canonicalized root.
50:         if let (Ok(rc), Ok(tc)) = (r.canonicalize(), target.canonicalize()) {
51:             if !tc.starts_with(&rc) {
52:                 return Err(GuardError::Traversal);
53:             }
54:         }
55:     }
56:     Ok(())
57: }
58: 
59: /// Resolve the frontend's virtual app-dir prefix, then validate.
60: pub fn guard_user_path(input: &str) -> Result<PathBuf, GuardError> {
61:     let resolved = crate::appdir::resolve(input);
62:     normalize_absolute(&resolved.to_string_lossy())
63: }
