1: // Shared focus-trap for dialogs and panels (03 §5.4: focus-trapped surfaces).
2: 
3: const FOCUSABLE = [
4:   "a[href]",
5:   "button:not([disabled])",
6:   "input:not([disabled])",
7:   "select:not([disabled])",
8:   "textarea:not([disabled])",
9:   '[tabindex]:not([tabindex="-1"])',
10: ].join(",");
11: 
12: export function trapTabKey(container: HTMLElement, e: KeyboardEvent): void {
13:   if (e.key !== "Tab") return;
14:   const focusables = Array.from(container.querySelectorAll<HTMLElement>(FOCUSABLE)).filter(
15:     (el) => el.offsetParent !== null
16:   );
17:   if (focusables.length === 0) {
18:     e.preventDefault();
19:     return;
20:   }
21:   const first = focusables[0];
22:   const last = focusables[focusables.length - 1];
23:   const active = document.activeElement as HTMLElement | null;
24:   // The dialog may focus a heading (tabindex="-1") on open. That element is
25:   // inside the container but is not a tab stop, so treat it as outside for
26:   // wrapping purposes instead of letting the first Tab escape the dialog.
27:   const onStop = active !== null && focusables.includes(active);
28: 
29:   if (e.shiftKey) {
30:     if (!onStop || active === first) {
31:       e.preventDefault();
32:       last.focus();
33:     }
34:   } else {
35:     if (!onStop || active === last) {
36:       e.preventDefault();
37:       first.focus();
38:     }
39:   }
40: }
41: 
42: export function focusFirstIn(container: HTMLElement): void {
43:   const target =
44:     container.querySelector<HTMLElement>("[data-autofocus]") ??
45:     container.querySelector<HTMLElement>(FOCUSABLE) ??
46:     container;
47:   target.focus();
48: }

