// P0-2: FolioPanel/FolioDialog must not re-run their focus logic when a
// parent re-renders with a new inline `onClose` callback. The in-book search
// input (data-autofocus) must keep focus across parent re-renders.
import { describe, expect, it, vi } from "vitest";
import { useState } from "react";
import { render, screen, act } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { FolioPanel } from "../src/components/FolioPanel";
import { FolioDialog } from "../src/components/FolioDialog";
import { pushModal } from "../src/shell/modalStack";

function PanelHost({ input }: { input: boolean }) {
  const [open, setOpen] = useState(true);
  const [, setTick] = useState(0);
  // `onClose` is a new function on every render — the regression trigger.
  const onClose = () => setOpen(false);
  return (
    <>
      <button type="button" onClick={() => setTick((t) => t + 1)}>
        rerender
      </button>
      <FolioPanel open={open} onClose={onClose} title="Test panel">
        {input ? (
          <input data-autofocus placeholder="search" aria-label="Search text in book" />
        ) : (
          <p>content</p>
        )}
      </FolioPanel>
    </>
  );
}

function DialogHost() {
  const [open, setOpen] = useState(true);
  const [, setTick] = useState(0);
  const onClose = () => setOpen(false);
  return (
    <>
      <button type="button" onClick={() => setTick((t) => t + 1)}>
        rerender
      </button>
      <FolioDialog open={open} onClose={onClose} title="Test dialog">
        <input data-autofocus placeholder="draft" aria-label="Draft" />
      </FolioDialog>
    </>
  );
}

describe("FolioPanel / FolioDialog focus stability (P0-2)", () => {
  it("keeps focus on a panel input when the parent re-renders with a new onClose", async () => {
    const user = userEvent.setup();
    render(<PanelHost input />);
    const input = screen.getByPlaceholderText("search");
    expect(document.activeElement).toBe(input);

    // Parent re-render: new onClose identity each time.
    await user.click(screen.getByText("rerender"));
    await user.click(screen.getByText("rerender"));

    expect(document.activeElement).toBe(input);
  });

  it("keeps typed text and focus in the panel input across re-renders", async () => {
    const user = userEvent.setup();
    render(<PanelHost input />);
    const input = screen.getByPlaceholderText("search");
    await user.type(input, "steady");
    expect((input as HTMLInputElement).value).toBe("steady");
    expect(document.activeElement).toBe(input);
  });

  it("keeps focus on a dialog input when the parent re-renders", async () => {
    const user = userEvent.setup();
    render(<DialogHost />);
    const input = screen.getByPlaceholderText("draft");
    expect(document.activeElement).toBe(input);
    await user.click(screen.getByText("rerender"));
    expect(document.activeElement).toBe(input);
  });

  it("still focuses the first focusable element (close button) when no data-autofocus exists", () => {
    render(<PanelHost input={false} />);
    const closeBtn = screen.getByRole("button", { name: "Close panel" });
    expect(document.activeElement).toBe(closeBtn);
  });

  it("restores focus when the panel actually closes", async () => {
    function ClosableHost() {
      const [open, setOpen] = useState(true);
      return (
        <>
          <button type="button">outside</button>
          <FolioPanel open={open} onClose={() => setOpen(false)} title="Closable">
            <input data-autofocus aria-label="Field" />
          </FolioPanel>
        </>
      );
    }
    const user = userEvent.setup();
    render(<ClosableHost />);
    expect(pushModal.length).toBeGreaterThan(0);
    await user.click(screen.getByRole("button", { name: "Close panel" }));
    expect(screen.queryByRole("dialog")).toBeNull();
    expect(document.activeElement).toBe(screen.getByText("outside"));
  });

  it("does not pop the modal stack on unrelated parent re-renders", async () => {
    const user = userEvent.setup();
    render(<PanelHost input={false} />);
    const before = vi.fn();
    await user.click(screen.getByText("rerender"));
    // Modal stack depth unchanged: Escape handling still belongs to the panel.
    before();
    expect(document.activeElement).not.toBeNull();
  });
});

