1: //! App-data directory resolution and the frontend's virtual path scheme.
2: //!
3: //! The TS layer builds every library path from a single virtual root
4: //! (`/folio-library`) so that the data model stays platform-neutral and the
5: //! Rust core never hard-codes Folio layout knowledge. At the OS boundary we
6: //! translate that virtual prefix to the real `%APPDATA%/Folio` directory
7: //! (02 §4: default app dir `%APPDATA%/Folio`, library under `library/`).
8: 
9: use std::path::{Path, PathBuf};
10: use std::sync::RwLock;
11: 
12: /// Virtual root used by the TypeScript layer.
13: pub const VIRTUAL_APP_DIR: &str = "/folio-library";
14: 
15: static APP_DIR: RwLock<Option<PathBuf>> = RwLock::new(None);
16: 
17: /// Resolve the default app dir. Tauri gives us
18: /// `%APPDATA%/<bundle-identifier>`; walk one level up and use `Folio` so the
19: /// on-disk layout matches the mobile/desktop spec exactly.
20: pub fn default_app_dir(tauri_app_data: Option<PathBuf>) -> PathBuf {
21:     #[cfg(target_os = "windows")]
22:     {
23:         if let Some(base) = tauri_app_data {
24:             if let Some(roaming) = base.parent() {
25:                 return roaming.join("Folio");
26:             }
27:             return base;
28:         }
29:     }
30:     tauri_app_data.unwrap_or_else(|| PathBuf::from(VIRTUAL_APP_DIR))
31: }
32: 
33: /// Install the process-wide app dir (called once from `setup`).
34: pub fn set_app_dir(dir: PathBuf) {
35:     if let Ok(mut slot) = APP_DIR.write() {
36:         *slot = Some(dir);
37:     }
38: }
39: 
40: pub fn app_dir() -> Option<PathBuf> {
41:     APP_DIR.read().ok().and_then(|slot| slot.clone())
42: }
43: 
44: /// Translate the virtual app dir prefix into the real app dir.
45: ///
46: /// Paths that do not start with the virtual root (native dialog picks, UNC
47: /// paths, `C:\...`) pass through untouched.
48: pub fn resolve(input: &str) -> PathBuf {
49:     resolve_with_base(input, app_dir().as_deref())
50: }
51: 
52: /// Pure form of [`resolve`] used by unit tests.
53: pub fn resolve_with_base(input: &str, base: Option<&Path>) -> PathBuf {
54:     if let Some(base) = base {
55:         if let Some(rest) = input.strip_prefix(VIRTUAL_APP_DIR) {
56:             let boundary = rest.is_empty() || rest.starts_with('/') || rest.starts_with('\\');
57:             if boundary {
58:                 let mut out = base.to_path_buf();
59:                 for seg in rest
60:                     .split(['/', '\\'])
61:                     .filter(|s| !s.is_empty() && *s != ".")
62:                 {
63:                     out.push(seg);
64:                 }
65:                 return out;
66:             }
67:         }
68:     }
69:     PathBuf::from(input)
70: }
