use std::path::{Path, PathBuf};
use thiserror::Error;

#[derive(Debug, Error)]
pub enum GuardError {
    #[error("path must be absolute")]
    NotAbsolute,
    #[error("path traversal detected")]
    Traversal,
    #[allow(dead_code)]
    #[error("invalid path component")]
