//! Native dialog pickers that double as the sandbox grant points.
//!
//! File commands only accept paths inside the app dir or granted this
//! session. The grants are made here, in Rust, when the user physically
//! picks a file — the webview never needs to ask for an arbitrary path.

use tauri::AppHandle;
use tauri_plugin_dialog::{DialogExt, FilePath};

fn grant_and_string(fp: FilePath) -> Option<String> {
    let path = fp.into_path().ok()?;
    crate::sandbox::grant(&path);
    Some(path.to_string_lossy().to_string())
}

async fn pick_files(
    app: AppHandle,
    title: &str,
    filter_name: &str,
    extensions: &[&str],
) -> Result<Vec<String>, String> {
    let title = title.to_string();
    let filter_name = filter_name.to_string();
    let extensions = extensions.to_vec();
    tauri::async_runtime::spawn_blocking(move || {
        let picked = app
            .dialog()
            .file()
            .set_title(title)
            .add_filter(filter_name, &extensions)
            .blocking_pick_files();
        Ok(picked
            .unwrap_or_default()
            .into_iter()
            .filter_map(grant_and_string)
            .collect())
    })
    .await
    .map_err(|e| e.to_string())?
}

async fn pick_file(
    app: AppHandle,
    title: &str,
    filter_name: &str,
    extensions: &[&str],
) -> Result<Option<String>, String> {
    let title = title.to_string();
    let filter_name = filter_name.to_string();
    let extensions = extensions.to_vec();
    tauri::async_runtime::spawn_blocking(move || {
        let picked = app
            .dialog()
            .file()
            .set_title(title)
            .add_filter(filter_name, &extensions)
            .blocking_pick_file();
        Ok(picked.and_then(grant_and_string))
    })
    .await
    .map_err(|e| e.to_string())?
}

async fn save_file(
    app: AppHandle,
    title: &str,
    default_name: String,
    filter_name: &str,
    extensions: &[&str],
) -> Result<Option<String>, String> {
    let title = title.to_string();
    let filter_name = filter_name.to_string();
    let extensions = extensions.to_vec();
    tauri::async_runtime::spawn_blocking(move || {
        let picked = app
            .dialog()
            .file()
            .set_title(title)
            .set_file_name(default_name)
            .add_filter(filter_name, &extensions)
            .blocking_save_file();
        Ok(picked.and_then(grant_and_string))
    })
    .await
    .map_err(|e| e.to_string())?
}

/// Import picker: multiple open dialog for books & articles.
#[tauri::command]
pub async fn pick_import_files(app: AppHandle) -> Result<Vec<String>, String> {
    pick_files(&app, "Import files", "Books & articles", &["epub", "html", "htm", "txt", "md"]).await
}

