/// Canonicalize with a parent fallback: save-dialog targets usually do not
/// exist yet, so canonicalize the parent and keep the final component.
pub fn canonicalize_best_effort(path: &Path) -> PathBuf {
    match path.canonicalize() {
        Ok(p) => p,
        Err(_) => {
            if let (Some(parent), Some(file)) = (path.parent(), path.file_name()) {
                match parent.canonicalize() {
                    Ok(p) => p.join(file),
                    Err(_) => path.to_path_buf(),
                }
            } else {
                path.to_path_buf()
            }
        }
    }
}

fn granted_paths() -> BTreeSet<PathBuf> {
    GRANTED
        .read()
        .ok()
        .and_then(|slot| slot.clone())
        .unwrap_or_default()
}

/// Grant one user-supplied path (and its parent directory) for this session.
/// Idempotent; canonicalizes so symlink/junction aliases collapse together.
pub fn grant(path: &Path) {
    if path.as_os_str().is_empty() {
        return;
    }
    let canonical = canonicalize_best_effort(path);
    if let Ok(mut slot) = GRANTED.write() {
        let set = slot.get_or_insert_with(BTreeSet::new);
        set.insert(canonical.clone());
        if let Some(parent) = canonical.parent() {
            set.insert(parent.to_path_buf());
        }
    }
}

