```ts
/** Subscribe to granted OS drops (`folio://drop-granted`, granted Rust-side
 * before the event). The handler receives readable files. */
export async function onDroppedFiles(
  handler: (files: PickedFile[]) => void
): Promise<() => void> {
  if (!isTauri()) return () => {};
  try {
    const { listen } = await import("@tauri-apps/api/event");
    return await listen<string[]>(DROP_GRANTED_EVENT, (event) => {
      const paths = Array.isArray(event.payload) ? event.payload : [];
      void filesFromTauriDrop(paths).then((files) => {
        if (files && files.length > 0) handler(files);
      });
    });
  } catch {
    return () => {};
  }
}
```

