/** Toggle fullscreen and return the new state. */
export async function toggleFullscreen(): Promise<boolean> {
  if (isTauri()) {
    try {
      const { getCurrentWindow } = await import("@tauri-apps/api/window");
      const win = getCurrentWindow();
      const next = !(await win.isFullscreen());
      await win.setFullscreen(next);
      markDom(next);
      return next;
    } catch {
      // The window call can be unavailable (permission, broken window);
      // report the unchanged state instead of throwing into the key handler.
      try {
        return await isFullscreen();
      } catch {
        return false;
      }
    }
  }
  if (typeof document === "undefined") return false;
  if (document.fullscreenElement) {
    await document.exitFullscreen();
    markDom(false);
    return false;
  }
  await document.documentElement.requestFullscreen();
  markDom(true);
  return true;
}

/** Esc/F11 exit path. */
export async function exitFullscreen(): Promise<void> {
  if (isTauri()) {
    try {
      const { getCurrentWindow } = await import("@tauri-apps/api/window");
      const win = getCurrentWindow();
      if (await win.isFullscreen()) await win.setFullscreen(false);
    } catch {
      /* best effort: the DOM class below still restores the chrome */
    }
    markDom(false);
    return;
  }
  if (typeof document !== "undefined" && document.fullscreenElement) {
    await document.exitFullscreen();
  }
  markDom(false);
}

