      handleError(e, {
        context: "reader.annotations.highlight",
        userMessage: "The highlight could not be updated.",
      });
      setSelection(null);
      return;
    }
    try {
      await refreshAnnotations(doc.docId);
    } catch (e) {
      handleError(e, { context: "reader.annotations.refresh" });
    }
    setSelection(null);
  },
