        turn("next");
        break;
      case "ArrowLeft":
      case "PageUp":
      case "ArrowUp":
        event.preventDefault();
        turn("previous");
        break;
      case " ":
        event.preventDefault();
        if (event.shiftKey) turn("previous");
        else turn("next");
        break;
      case "Home":
        event.preventDefault();
        jump(0);
        break;
      case "End":
        event.preventDefault();
        jump(100);
        break;
      case "MediaTrackNext":
        event.preventDefault();
        turn("next");
        break;
      case "MediaTrackPrevious":
        event.preventDefault();
        turn("previous");
        break;
