  noteEditorOpen,
  quoteCardOpen,
  chrome.setMenu,
  chrome.togglePanel,
  chrome.toggleFocusMode,
  chrome.closePanel,
  chrome.exitFocusMode,
  reportNavigation,
  showNavNotice,
]);

