  (location: string | null | undefined): string | null => {
    if (!doc || !location) return null;
    const href = hrefOf(location);
    if (!href) return null;
    const chapter = doc.meta.chapters.find((c) => hrefMatches(c.href, href));
    return chapter?.id ?? null;
  },
  [doc]
);

