54: function editDistance(a: string, b: string): number {
55:   if (a === b) return 0;
56:   if (!a.length) return b.length;
57:   if (!b.length) return a.length;
58:   const prev = Array.from({ length: b.length + 1 }, (_, i) => i);
59:   for (let i = 1; i <= a.length; i++) {
60:     let cur = i;
61:     for (let j = 1; j <= b.length; j++) {
62:       const cost = a[i - 1] === b[j - 1] ? 0 : 1;
63:       const v = Math.min(prev[j] + 1, cur + 1, prev[j - 1] + cost);
64:       prev[j - 1] = cur;
65:       cur = v;
66:     }
67:     prev[b.length] = cur;
68:   }
69:   return prev[b.length];
