22: function decodeEntities(s: string): string {
23:   return s.replace(/&(#x?[0-9a-fA-F]+|[a-zA-Z]+);/g, (whole, entity: string) => {
24:     const named = HTML_ENTITIES[entity];
25:     if (named !== undefined) return named;
26:     if (entity.startsWith("#x") || entity.startsWith("#X")) {
27:       const code = Number.parseInt(entity.slice(2), 16);
28:       return Number.isFinite(code) ? String.fromCodePoint(code) : whole;
29:     }
30:     if (entity.startsWith("#")) {
31:       const code = Number.parseInt(entity.slice(1), 10);
32:       return Number.isFinite(code) ? String.fromCodePoint(code) : whole;
33:     }
