41: export function textLengthOfHtml(bytes: Uint8Array): number {
42:   let html: string;
43:   try {
44:     html = strFromU8(bytes);
45:   } catch {
46:     return 0;
47:   }
48:   const text = decodeEntities(
49:     html
50:       .replace(/<\?[\s\S]*?\?>/g, " ")
51:       .replace(/<!--[\s\S]*?-->/g, " ")
52:       .replace(/<(script|style|head)\b[\s\S]*?<\/\1>/gi, " ")
53:       .replace(/<[^>]+>/g, " "),
