70:  * navigator's `go()`, percent jumps, and the progress pillar.
71:  */
72: export function generatePositions(
73:   publication: Publication,
74:   zip: Record<string, Uint8Array>,
75: ): Locator[] {
76:   const resources: PositionedLink[] = publication.readingOrder.items.map((link) => {
77:     const bytes = zip[link.href] ?? zip[decodeHref(link.href)];
78:     const length = bytes ? textLengthOfHtml(bytes) : 0;
79:     return { link, length, count: Math.max(1, Math.ceil(length / POSITION_LENGTH)) };
80:   });
81: 
82:   const total = resources.reduce((sum, r) => sum + r.count, 0);
83:   const positions: Locator[] = [];
84:   let index = 0;
85:   for (const resource of resources) {
86:     for (let i = 0; i < resource.count; i++) {
87:       const progression = resource.count <= 1 ? 0 : i / resource.count;
88:       positions.push(
89:         new Locator({
90:           href: resource.link.href,
91:           type: resource.link.type ?? "application/xhtml+xml",
92:           title: resource.link.title,
93:           locations: new LocatorLocations({
94:             position: index + 1,
95:             progression,
96:             totalProgression: total > 0 ? index / total : 0,
97:           }),
98:         }),
99:       );
100:       index += 1;
101:     }
102:   }
103:   return positions;
