116:  * instead of the quantized `totalProgression` stamped on each position.
117:  */
118: export function progressionForLocator(locator: Locator, positions: Locator[]): number | null {
119:   if (positions.length === 0) {
120:     return locator.locations.totalProgression ?? locator.locations.progression ?? null;
121:   }
122:   const href = locator.href.split("#")[0];
123:   const inResource = locator.locations.progression ?? 0;
124:   let firstForHref = -1;
125:   let countForHref = 0;
126:   for (let i = 0; i < positions.length; i++) {
127:     if (positions[i].href !== href) continue;
128:     if (firstForHref === -1) firstForHref = i;
129:     countForHref += 1;
130:   }
131:   if (firstForHref === -1) {
132:     return locator.locations.totalProgression ?? null;
133:   }
134:   return Math.min(1, (firstForHref + inResource * countForHref) / positions.length);
135: }
136: 
137: /** Locator for a 0..1 publication progression (scrubber / resume fallback). */
138: export function locatorForProgression(percent: number, positions: Locator[]): Locator | null {
139:   if (positions.length === 0) return null;
140:   const p = Math.min(1, Math.max(0, percent));
141:   const idx = Math.min(positions.length - 1, Math.round(p * (positions.length - 1)));
142:   return positions[idx];
143: }

