    const idx = this.docs.length;
    const tokens = tokenizeText(`${doc.title} ${doc.text}`);
    const titleTokens = new Set(tokenizeText(doc.title));
    this.docs.push({ doc, len: Math.max(1, tokens.length), titleTokens, corpus: null });

